def validate_frame_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != FRAME_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    ports = config["ports"]
    max_frame = config["max_frame"]
    if not isinstance(ports, list) or not ports:
        raise InvalidInput("ports must be a non-empty list")
    if not all(isinstance(p, str) and p for p in ports):
        raise InvalidInput("ports must be non-empty strings")
    if len(set(ports)) != len(ports):
        raise InvalidInput("ports must be distinct")
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return ports, max_frame


def validate_frame_check_frames(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    port_set = set(ports)
    result = []
    prev_t = None
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FRAME_CHECK_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        length = frame["length"]
        fcs = frame["fcs"]
        alignment = frame["alignment"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        if not _is_int(length) or length < 0:
            raise InvalidInput("bad length")
        if not isinstance(fcs, bool):
            raise InvalidInput("bad fcs")
        if not isinstance(alignment, bool):
            raise InvalidInput("bad alignment")
        result.append((t, port, length, fcs, alignment))
    return result


def frame_check(frames, ports, max_frame):
    counts = {
        name: {"good": 0, "runt": 0, "giant": 0, "alignment": 0, "bad_fcs": 0}
        for name in ports
    }
    results = []
    for t, port, length, fcs, alignment in frames:
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        counts[port][cls] += 1
        results.append({"t": t, "port": port, "class": cls})
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "good": counts[name]["good"],
                "runt": counts[name]["runt"],
                "giant": counts[name]["giant"],
                "alignment": counts[name]["alignment"],
                "bad_fcs": counts[name]["bad_fcs"],
            }
            for name in ports
        ],
    }


FORWARD_CHECK_CONFIG_KEYS = frozenset({"ports", "age", "max_frame"})
FORWARD_CHECK_FRAME_KEYS = frozenset(
    {"t", "port", "src", "dst", "vlan", "length", "fcs", "alignment"}
)


def validate_forward_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != FORWARD_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    # ports/age 与新式 forward 契约一致，复用其全量校验
    ports, age = validate_forward_config_v2(
        {"ports": config["ports"], "age": config["age"]}
    )
    return ports, age, max_frame


def validate_forward_check_frames(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    base = []
    extras = []
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FORWARD_CHECK_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        length = frame["length"]
        fcs = frame["fcs"]
        alignment = frame["alignment"]
        if not _is_int(length) or length < 0:
            raise InvalidInput("bad length")
        if not isinstance(fcs, bool):
            raise InvalidInput("bad fcs")
        if not isinstance(alignment, bool):
            raise InvalidInput("bad alignment")
        # t/port/src/dst/vlan 与新式帧契约一致，复用其全量校验
        base.append(
            {key: frame[key] for key in ("t", "port", "src", "dst", "vlan")}
        )
        extras.append((length, fcs, alignment))
    checked = validate_frames_v2(base, ports)
    return [
        (t, port, src, dst, vlan, length, fcs, alignment)
        for (t, port, src, dst, vlan), (length, fcs, alignment) in zip(
            checked, extras
        )
    ]


def forward_check(frames, ports, age, max_frame):
    by_name = {port["name"]: port for port in ports}
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    for t, port_name, src, dst, tag, length, fcs, alignment in frames:
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":  # 非 good 丢弃且不学习、不转发、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            continue
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # 拒绝帧丢弃且不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            continue
        vlan_stats[vlan]["rx"] += 1
        egress = []
        action = "drop"
        if ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target = by_name[hit[0]]
                if target["up"] and vlan in target["allowed"]:
                    egress = [hit[0]]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in ports
                    if vlan in port["allowed"]
                    and port["up"]
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append(
            {"t": t, "class": cls, "action": action, "ports": out_ports}
        )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


LINK_STATE_CONFIG_KEYS = frozenset({"ports", "delay"})
LINK_STATE_PORT_KEYS = frozenset({"name", "rates", "modes"})
LINK_STATE_EVENT_KEYS = frozenset(
    {"t", "port", "admin", "peer", "rates", "modes"}
)
LINK_STATE_RATES = (10, 100, 1000, 10000)
LINK_STATE_MODES = ("half", "full")


def _validate_link_state_rates(rates):
    # rates 为 10/100/1000/10000 的非空严格递增子集
    if not isinstance(rates, list) or not rates:
        raise InvalidInput("bad rates")
    if any(
        not _is_int(rate) or rate not in LINK_STATE_RATES for rate in rates
    ):
        raise InvalidInput("bad rates")
    if any(rates[i] >= rates[i + 1] for i in range(len(rates) - 1)):
        raise InvalidInput("rates not increasing")
    return tuple(rates)


def _validate_link_state_modes(modes):
    # modes 为 half/full 的非空子序列（保序、互异、非空）
    if not isinstance(modes, list) or not modes:
        raise InvalidInput("bad modes")
    if any(
        not isinstance(mode, str) or mode not in LINK_STATE_MODES
        for mode in modes
    ):
        raise InvalidInput("bad modes")
    if len(set(modes)) != len(modes):
        raise InvalidInput("bad modes")
    if list(modes) != sorted(modes, key=LINK_STATE_MODES.index):
        raise InvalidInput("modes not a subsequence")
    return tuple(modes)


def validate_link_state_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != LINK_STATE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    ports = config["ports"]
    if not isinstance(ports, list) or not ports:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    result = []
    for port in ports:
        if (
            not isinstance(port, dict)
            or frozenset(port) != LINK_STATE_PORT_KEYS
        ):
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        result.append(
            (
                name,
                _validate_link_state_rates(port["rates"]),
                _validate_link_state_modes(port["modes"]),
            )
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    return result, delay


def validate_link_state_events(events, ports):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    port_set = {name for name, _, _ in ports}
    result = []
    prev_t = None
    for event in events:
        if (
            not isinstance(event, dict)
            or frozenset(event) != LINK_STATE_EVENT_KEYS
        ):
            raise InvalidInput("bad event")
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        port = event["port"]
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        admin = event["admin"]
        peer = event["peer"]
        if not isinstance(admin, bool) or not isinstance(peer, bool):
            raise InvalidInput("bad admin/peer")
        rates = _validate_link_state_rates(event["rates"])
        modes = _validate_link_state_modes(event["modes"])
        result.append((t, port, admin, peer, rates, modes))
    return result


def link_state(events, ports, delay):
    caps = {name: (rates, modes) for name, rates, modes in ports}
    # 生效状态：("down",)/("bad",)/("up", rate, mode)；两状态初始皆 false
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)；仅 up 目标需协商
    results = []
    for t, port, admin, peer, rates, modes in events:
        # 先完成截止 <= t 的协商
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        # 再替换该口并计算目标
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            # 目标变化即进入 wait 并于 t+delay 完成
            pending[port] = (target[1], target[2], t + delay)
        else:
            # down/bad 立即生效
            pending.pop(port, None)
            committed[port] = target
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
            else:
                state, rate, mode = now[0], None, None
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
    return {"results": results}


def link_state_work(events, ports, delay, limit):
    """link-state 的工作量预演：独立 committed/pending 状态，无副作用。

    W 初值 0；逐事件在完成截止 <= t 的协商前，令 Q 为 pending 数，累计
    Q+1；再沿用 link_state 规则完成到期项、替换该口状态并计算
    down/bad/up 目标，目标未变不重置，变为 up 则进入 wait。等于上限
    合法，首次超过即抛 LinkWorkLimit，不访问后续事件。
    """
    caps = {name: (rates, modes) for name, rates, modes in ports}
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)
    work = 0
    for t, port, admin, peer, rates, modes in events:
        work += len(pending) + 1
        if work > limit:
            raise LinkWorkLimit()
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
        else:
            pending.pop(port, None)
            committed[port] = target


